package android.os;import java.util.concurrent.ConcurrentLinkedQueue;public final class Handler {public static final ConcurrentLinkedQueue<Runnable> QUEUE=new ConcurrentLinkedQueue<>();public Handler(Looper l){}public boolean post(Runnable r){QUEUE.add(r);return true;}public void removeCallbacksAndMessages(Object token){QUEUE.clear();}public static void drain(){Runnable r;while((r=QUEUE.poll())!=null)r.run();}}
